#!/usr/bin/env node
// Give the generated iOS project its Associated Domains entitlement.
//
// `ios/` holds only HANDOFF.md and App.entitlements (a template): the native
// Xcode project, its Podfile and its Info.plist are generated by the Capacitor
// CLI on every run ('cap add ios' / 'cap sync ios'), so an entitlements file
// committed inside ios/App/ would be overwritten and the CODE_SIGN_ENTITLEMENTS
// build setting would be dropped. Like scripts/ios-min-os.mjs, this has to be
// re-applied after the sync and before anything is compiled.
//
// Without it, iOS never claims a fantasysportsnetwork.app link. The build is
// green, the upload succeeds, and every shared article link opens Safari
// instead of the app — the failure is invisible everywhere except on a device.
//
// Run from the repo root, after 'cap sync ios':
//   node scripts/ios-associated-domains.mjs
//
// Two edits, both idempotent:
//   1. copy ios/App.entitlements -> ios/App/App/App.entitlements
//   2. set CODE_SIGN_ENTITLEMENTS = App/App.entitlements in every build
//      configuration of the App target
//
// The Apple Developer portal side (the Associated Domains capability on the
// App ID) is not scriptable from here; Xcode enables it during an archive
// exported with -allowProvisioningUpdates. See ios/HANDOFF.md.
import { readFileSync, writeFileSync, copyFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const TAG = '[ios-associated-domains]';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const TEMPLATE = join(root, 'ios', 'App.entitlements');
const TARGET_DIR = join(root, 'ios', 'App', 'App');
const TARGET = join(TARGET_DIR, 'App.entitlements');
const PBXPROJ = join(root, 'ios', 'App', 'App.xcodeproj', 'project.pbxproj');

// The path as the Xcode target has to see it: relative to the .xcodeproj's
// parent (ios/App), which is where every other path in the project is anchored.
const SETTING_VALUE = 'App/App.entitlements';
const SETTING = `CODE_SIGN_ENTITLEMENTS = ${SETTING_VALUE};`;

// The App target is the only one whose Info.plist is App/Info.plist, in both
// the Debug and the Release configuration. Anchoring on the bundle identifier
// instead would miss a project whose configs inherit it from a variable.
const APP_TARGET_MARKER = 'INFOPLIST_FILE = App/Info.plist;';

function fail(title, detail) {
  if (process.env.GITHUB_ACTIONS) {
    console.log(`::error title=${title}::${detail.replace(/\s+/g, ' ').trim()}`);
  }
  console.error(`${TAG} ${title}: ${detail}`);
  process.exit(1);
}

// ---------------------------------------------------------------------------
// 1. The entitlements file itself.

if (!existsSync(TEMPLATE)) {
  fail(
    'Entitlements template missing',
    `Expected ${TEMPLATE}. It is committed to the repo and is the only copy of the ` +
      'Associated Domains list; without it the binary claims no universal links at all.'
  );
}

if (!existsSync(TARGET_DIR)) {
  fail(
    'Native iOS project missing',
    `Expected ${TARGET_DIR} after the Capacitor sync. Run 'npx cap add ios' (first time) ` +
      "or 'npx cap sync ios' before this script."
  );
}

const template = readFileSync(TEMPLATE, 'utf8');
const domains = [...template.matchAll(/<string>applinks:([^<]+)<\/string>/g)].map((m) => m[1]);
if (domains.length === 0) {
  fail(
    'No applinks domains in the template',
    `${TEMPLATE} declares no <string>applinks:…</string> entries, so the entitlement would ` +
      'be empty and iOS would claim nothing. Add the hosts that serve the AASA.'
  );
}

mkdirSync(TARGET_DIR, { recursive: true });
copyFileSync(TEMPLATE, TARGET);
console.log(`${TAG} ios/App.entitlements -> ios/App/App/App.entitlements (${domains.length} domain(s))`);
for (const domain of domains) console.log(`${TAG}   applinks:${domain}`);

// ---------------------------------------------------------------------------
// 2. The build setting that makes Xcode compile it into the signed binary.

if (!existsSync(PBXPROJ)) {
  fail(
    'Xcode project missing',
    `Expected ${PBXPROJ} after the Capacitor sync. The entitlements file would sit in the ` +
      'project folder unreferenced and the archive would ship without it.'
  );
}

const pbxproj = readFileSync(PBXPROJ, 'utf8');

if (!pbxproj.includes(APP_TARGET_MARKER)) {
  fail(
    'No App target build settings found',
    `project.pbxproj contains no "${APP_TARGET_MARKER}" line, so this script cannot tell which ` +
      'build configurations belong to the App target. The Capacitor project template changed; ' +
      'update scripts/ios-associated-domains.mjs to match it.'
  );
}

let seen = 0;
let added = 0;
let alreadySet = 0;
const patched = pbxproj.replace(
  new RegExp(`([ \\t]*)${APP_TARGET_MARKER.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'g'),
  (whole, indent, offset, source) => {
    seen++;
    // Only look inside the enclosing buildSettings block, so a value already set
    // on a different configuration is never mistaken for this one's.
    const blockStart = source.lastIndexOf('buildSettings = {', offset);
    const blockEnd = source.indexOf('};', offset);
    const block = blockStart >= 0 && blockEnd > blockStart ? source.slice(blockStart, blockEnd) : '';
    if (block.includes('CODE_SIGN_ENTITLEMENTS')) {
      alreadySet++;
      return whole;
    }
    added++;
    return `${indent}${SETTING}\n${whole}`;
  }
);

if (added > 0) writeFileSync(PBXPROJ, patched, 'utf8');
console.log(
  `${TAG} project.pbxproj: ${added} of ${seen} App build configuration(s) given ` +
    `${SETTING}${alreadySet ? ` (${alreadySet} already had one)` : ''}`
);

// A configuration that already carried a *different* entitlements path is the
// one case worth naming: the archive would sign against that file, not this one.
const conflicting = [...patched.matchAll(/CODE_SIGN_ENTITLEMENTS = ([^;]+);/g)]
  .map((m) => m[1].trim().replace(/^"|"$/g, ''))
  .filter((value) => value !== SETTING_VALUE);
if (conflicting.length) {
  fail(
    'Conflicting entitlements path',
    `project.pbxproj points a build configuration at ${conflicting.join(', ')} instead of ` +
      `${SETTING_VALUE}. That file, not ios/App.entitlements, is what gets signed — reconcile them ` +
      'before archiving, or universal links ship silently disabled.'
  );
}

console.log(`${TAG} associated domains are wired into the Xcode project`);

// Capacitor's push plugin needs both AppDelegate callbacks. The native project
// is regenerated in CI, so wire them after sync rather than patching generated files.
const delegatePath = join(TARGET_DIR, 'AppDelegate.swift');
const delegate = readFileSync(delegatePath, 'utf8');
const callbacks = [
  ['didRegisterForRemoteNotificationsWithDeviceToken', 'capacitorDidRegisterForRemoteNotifications',
    '    func application(_ application: UIApplication, didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data) {\n' +
    '        NotificationCenter.default.post(name: .capacitorDidRegisterForRemoteNotifications, object: deviceToken)\n    }'],
  ['didFailToRegisterForRemoteNotificationsWithError', 'capacitorDidFailToRegisterForRemoteNotifications',
    '    func application(_ application: UIApplication, didFailToRegisterForRemoteNotificationsWithError error: Error) {\n' +
    '        NotificationCenter.default.post(name: .capacitorDidFailToRegisterForRemoteNotifications, object: error)\n    }'],
];
let updatedDelegate = delegate;
for(const [method, event, implementation] of callbacks){
  if(updatedDelegate.includes(method)){
    if(!updatedDelegate.includes(event)) fail('Conflicting push callback', `${method} exists without forwarding ${event}.`);
    continue;
  }
  const classEnd = updatedDelegate.lastIndexOf('}');
  if(classEnd < 0) fail('Invalid AppDelegate', 'Could not locate the AppDelegate closing brace.');
  updatedDelegate = updatedDelegate.slice(0, classEnd) + '\n' + implementation + '\n' + updatedDelegate.slice(classEnd);
}
if(updatedDelegate !== delegate) writeFileSync(delegatePath, updatedDelegate);
console.log(`${TAG} APNs success/error callbacks are wired into AppDelegate`);
